F2 = [['kubelet /metrics/resource', 'container_cpu_usage_seconds_total'], ['累计计数器', '两次读数相减'], ['(17.24-6.18)/36.9', '= 300m'], ['kubectl top pod burn', '301m']]
F3 = [['fresh Pod Ready', '0.5 秒'], ['kubectl top', 'podmetrics … not found'], ['第一次出现', '创建后 23 秒']]
